#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool walk(const char *g, size_t r, size_t c, long y, long x, char p, bool *v) {
    if (x < 0 || y < 0 || (size_t)x >= c || (size_t)y >= r)
        return false;
    size_t i = (size_t)y * c + (size_t)x;
    if (v[i] || g[i] != p)
        return false;
    v[i] = true;
    if ((p == 'X' && (size_t)x == c - 1) || (p == 'O' && (size_t)y == r - 1))
        return true;
    int dy[] = {0, 0, 1, -1, 1, -1}, dx[] = {1, -1, 0, 0, -1, 1};
    for (int k = 0; k < 6; k++)
        if (walk(g, r, c, y + dy[k], x + dx[k], p, v))
            return true;
    return false;
}
char winner(const char *const *lines, size_t r) {
    if (!r)
        return 0;
    size_t c = 0;
    for (const char *p = lines[0]; *p; p++)
        if (!isspace((unsigned char)*p))
            c++;
    if (!c)
        return 0;
    char *g = (char *)malloc(r * c);
    for (size_t y = 0; y < r; y++) {
        size_t x = 0;
        for (const char *p = lines[y]; *p; p++)
            if (!isspace((unsigned char)*p)) {
                if (x >= c) {
                    free(g);
                    return 0;
                }
                g[y * c + x++] = *p;
            }
        if (x != c) {
            free(g);
            return 0;
        }
    }
    bool *v = (bool *)calloc(r * c, sizeof(bool));
    char result = 0;
    for (size_t y = 0; y < r && !result; y++)
        if (walk(g, r, c, (long)y, 0, 'X', v))
            result = 'X';
    memset(v, 0, r * c * sizeof(bool));
    for (size_t x = 0; x < c && !result; x++)
        if (walk(g, r, c, 0, (long)x, 'O', v))
            result = 'O';
    free(g);
    free(v);
    return result;
}

