#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    const char *a[] = {"X X X", " O O .", "  . . O"};
    assert(winner(a, 3) == 'X');
    const char *b[] = {"O X .", "O X .", "O . X"};
    assert(winner(b, 3) == 'O');
    const char *c[] = {"X .", ". X"};
    assert(winner(c, 2) == 0);
    const char *d[] = {"X"};
    assert(winner(d, 1) == 'X');

    return 0;
}
